<?php

declare(strict_types=1);

function student_history_date(?string $value,string $format='d/m/Y H:i'): string
{
    if(!$value)return '—';
    return (new DateTimeImmutable($value,new DateTimeZone('UTC')))->setTimezone(new DateTimeZone('Europe/Zurich'))->format($format);
}

function render_student_admin_panel(array $student): void
{
    $id=(int)$student['id'];
    ?><div class="modal-header"><div><p class="eyebrow mb-1"><?=e(t('Gestion de l’élève'))?></p><h2 class="modal-title fs-5" id="student-admin-title"><?=e($student['first_name'].' '.$student['last_name'])?></h2></div><?php render_student_admin_menu($id); ?></div>
    <div class="modal-body" data-admin-student="<?=$id?>"><ul class="nav nav-tabs mb-3" role="tablist"><?php foreach(['information'=>'Informations','enrollments'=>'Inscriptions','history'=>'Historique'] as $key=>$label): ?><li class="nav-item" role="presentation"><button class="nav-link <?=$key==='information'?'active':''?>" id="admin-tab-<?=$key?>" data-bs-toggle="tab" data-bs-target="#admin-pane-<?=$key?>" data-admin-tab="<?=$key?>" type="button" role="tab" aria-controls="admin-pane-<?=$key?>" aria-selected="<?=$key==='information'?'true':'false'?>"><?=e(t($label))?></button></li><?php endforeach; ?></ul>
    <div class="tab-content"><section class="tab-pane fade show active" id="admin-pane-information" role="tabpanel" aria-labelledby="admin-tab-information"><dl class="student-admin-information"><?php foreach(['first_name'=>'Prénom','last_name'=>'Nom','email'=>'Courriel','phone'=>'Téléphone','class_group'=>'Groupe classe','login_code'=>'Code élève'] as $key=>$label): ?><div><dt><?=e(t($label))?></dt><dd><?=e($student[$key]?:'—')?></dd></div><?php endforeach; ?></dl><?php render_student_secondary_email_form($student,true); ?><div class="student-admin-account"><?php render_student_management_sections($student,'account'); ?></div></section>
    <section class="tab-pane fade" id="admin-pane-enrollments" role="tabpanel" aria-labelledby="admin-tab-enrollments"><?php render_student_management_sections($student,'enrollments'); ?></section>
    <section class="tab-pane fade" id="admin-pane-history" role="tabpanel" aria-labelledby="admin-tab-history"><div class="student-history-heading"><h3><?=e(t('Suivi administratif'))?></h3><button type="button" class="btn btn-outline-primary" data-add-followup="<?=$id?>"><i class="bi bi-journal-plus"></i> <?=e(t('Ajouter un suivi'))?></button></div><div data-student-history role="region" aria-label="<?=e(t('Historique de l’élève'))?>"></div></section></div></div>
    <?php
}

function render_student_admin_menu(int $studentId): void
{
    ?><div class="dropdown student-admin-menu"><button type="button" class="btn btn-light" data-bs-toggle="dropdown" aria-expanded="false" aria-label="<?=e(t('Actions de la fiche'))?>"><i class="bi bi-three-dots-vertical" aria-hidden="true"></i></button><ul class="dropdown-menu dropdown-menu-end"><?php foreach(['pdf'=>'Exporter en PDF','markdown'=>'Exporter en Markdown'] as $format=>$label): ?><li><a class="dropdown-item" data-admin-export="<?=$format?>" href="<?=e(route('student-admin-export',['student'=>$studentId,'format'=>$format]))?>"><i class="bi <?=$format==='pdf'?'bi-file-earmark-pdf':'bi-filetype-md'?>" aria-hidden="true"></i> <?=e(t($label))?></a></li><?php endforeach; ?><li><hr class="dropdown-divider"></li><li><button type="button" class="dropdown-item" data-bs-dismiss="modal"><?=e(t('Fermer'))?></button></li></ul></div><?php
}

function render_student_history(array $history): void
{
    $studentId=(int)$history['student_id'];
    ?><div class="student-history-list"><?php foreach($history['items'] as $entry):
        $isNote=$entry['source']==='followup';
        $participants=implode(', ',array_column(StudentAdminHistory::otherParticipants($entry,$studentId),'name'));
        ?><article class="student-history-entry" data-history-source="<?=e($entry['source'])?>" data-history-id="<?=(int)$entry['id']?>">
        <header><p class="student-history-byline"><strong><?=e(t(StudentAdminHistory::KINDS[$entry['kind']]??'Message'))?></strong> <span><?=e(t('créé par :name, le :date',['name'=>$entry['author_name']?:t('Enseignant'),'date'=>student_history_date($entry['created_at'])]))?></span></p>
        <?php if($entry['editable']): $edit=['id'=>(int)$entry['id'],'revision'=>(int)$entry['revision'],'kind'=>$entry['kind'],'course_id'=>$entry['course_id']??0,'occurred_at'=>student_history_date($entry['occurred_at'],'Y-m-d\TH:i'),'title'=>$entry['title'],'body'=>$entry['body'],'students'=>array_map('intval',array_column($entry['participants'],'id'))]; ?>
          <div class="student-history-entry-actions"><button type="button" class="btn btn-sm btn-outline-secondary" data-edit-followup="<?=e(json_encode($edit,JSON_UNESCAPED_UNICODE))?>" aria-label="<?=e(t('Modifier le suivi'))?>"><i class="bi bi-pencil"></i></button><button type="button" class="btn btn-sm btn-outline-danger" data-delete-followup="<?=(int)$entry['id']?>" data-revision="<?=(int)$entry['revision']?>" aria-label="<?=e(t('Supprimer le suivi'))?>"><i class="bi bi-trash3"></i></button></div>
        <?php endif; ?></header>
        <?php if($participants!==''): ?><p class="student-history-participants"><?=e(t('Autres participants'))?> : <?=e($participants)?></p><?php endif; ?>
        <details class="student-history-content"><summary><span><strong><?=e(t('Concerne'))?></strong> : <?=e(($entry['course_title']!==''?$entry['course_title'].' / ':'').$entry['title'])?></span><i class="bi bi-chevron-right" aria-hidden="true"></i></summary><div class="student-history-expanded">
          <div class="content-block"><?=Markdown::render($entry['body'])?></div>
          <?php if(!$isNote): ?><footer><p><?=e(t('À'))?> : <?=e($entry['email'])?><?=$entry['cc']?' · CC : '.e($entry['cc']):''?><?=$entry['bcc']?' · CCI : '.e($entry['bcc']):''?></p><p><?=e(t($entry['read_at']?'Lu dans l’application':'Non lu dans l’application'))?><?php if($entry['mail_status']): ?> · <?=e(t(['sent'=>'Envoyé','pending'=>'En attente','failed'=>'En échec'][$entry['mail_status']]))?><?php if($entry['sent_at']): ?> <?=e(student_history_date($entry['sent_at']))?><?php endif; ?><?php endif; ?></p><a href="<?=e(route('pathway',['course'=>(int)$entry['course_id']]))?>#announcement-<?=(int)$entry['id']?>"><?=e(t('Voir l’annonce'))?></a></footer><?php elseif($entry['revision']>0): ?><p><em><?=e(t('Modifié le :date',['date'=>student_history_date($entry['updated_at'])]))?></em></p><?php endif; ?>
        </div></details>
        </article>
    <?php endforeach; ?><?php if(!$history['items']): ?><p class="empty"><?=e(t('Aucun suivi enregistré pour cet élève.'))?></p><?php endif; ?></div>
    <nav class="student-history-pagination" aria-label="<?=e(t('Pages de l’historique'))?>"><button type="button" class="btn btn-outline-secondary" data-history-page="<?=$history['page']-1?>" <?=$history['page']<=1?'disabled':''?>><?=e(t('Précédent'))?></button><span><?=e(t('Page :number',['number'=>$history['page']]))?></span><button type="button" class="btn btn-outline-secondary" data-history-page="<?=$history['page']+1?>" <?=$history['has_more']?'':'disabled'?>><?=e(t('Suivant'))?></button></nav><?php
}

function render_student_admin_modals(array $courses,array $students,int $defaultCourse=0): void
{
    $teacherId=(int)actor()['id'];$templates=AnnouncementMessages::templates(db(),$teacherId);
    if($defaultCourse>0)$students=all("SELECT u.id,u.name,u.class_group,GROUP_CONCAT(DISTINCT e.course_id) AS course_ids FROM users u LEFT JOIN enrollments e ON e.student_id=u.id WHERE u.role='student' AND (u.managed_by=:teacher OR EXISTS(SELECT 1 FROM enrollments own JOIN courses c ON c.id=own.course_id WHERE own.student_id=u.id AND (c.teacher_id=:teacher OR EXISTS(SELECT 1 FROM course_teachers ct WHERE ct.course_id=c.id AND ct.teacher_id=:teacher)))) GROUP BY u.id ORDER BY u.class_group,u.last_name,u.first_name",[':teacher'=>$teacherId]);
    $courses=all('SELECT c.id,c.title FROM courses c WHERE c.teacher_id=? OR EXISTS(SELECT 1 FROM course_teachers ct WHERE ct.course_id=c.id AND ct.teacher_id=?) ORDER BY c.title',[$teacherId,$teacherId]);
    $labels=['actions'=>t('Actions de la fiche'),'close'=>t('Fermer'),'loading'=>t('Chargement…'),'error'=>t('L’opération a échoué. Votre saisie est conservée.'),'saved'=>t('Suivi enregistré.'),'deleted'=>t('Suivi supprimé.'),'deleteConfirm'=>t('Supprimer ce suivi dans les profils de tous ses participants ?'),'discard'=>t('Fermer sans enregistrer ce suivi ?'),'empty'=>t('Sélectionnez au moins un élève.')];
    ?><div class="modal fade" id="student-admin-modal" tabindex="-1" aria-labelledby="student-admin-title" aria-hidden="true" data-admin-labels="<?=e(json_encode($labels,JSON_UNESCAPED_UNICODE))?>"><div class="modal-dialog modal-xl modal-dialog-scrollable"><div class="modal-content" data-student-admin-content></div></div></div>
    <div class="modal fade" id="student-followup-modal" tabindex="-1" aria-labelledby="followup-modal-title" aria-hidden="true" data-followup-course="<?=$defaultCourse?>" data-followup-templates="<?=e(json_encode($templates,JSON_UNESCAPED_UNICODE))?>"><div class="modal-dialog modal-xl modal-dialog-scrollable"><div class="modal-content"><form method="post" data-followup-form><?=csrf_field()?><input type="hidden" name="followup_id" value="0"><input type="hidden" name="revision" value="0"><input type="hidden" name="request_key" value="<?=e(bin2hex(random_bytes(24)))?>"><div class="modal-header"><h2 class="modal-title fs-5" id="followup-modal-title"><?=e(t('Suivi administratif'))?></h2><button type="button" class="btn-close" data-bs-dismiss="modal" aria-label="<?=e(t('Fermer'))?>"></button></div><div class="modal-body"><div class="followup-grid"><section><h3><?=e(t('Participants'))?></h3><label class="check plain"><input type="checkbox" data-followup-all> <?=e(t('Tous les élèves affichés'))?></label><input type="search" data-followup-search placeholder="<?=e(t('Rechercher un élève'))?>" aria-label="<?=e(t('Rechercher un élève'))?>"><div class="followup-participants"><?php foreach($students as $student): ?><label data-followup-participant="<?=(int)$student['id']?>" data-participant-courses="<?=e($student['course_ids']??'')?>"><input type="checkbox" name="students[]" value="<?=(int)$student['id']?>"><span><b><?=e($student['name'])?></b><small><?=e($student['class_group'])?></small></span></label><?php endforeach; ?></div></section><section><div class="two-fields"><label class="field"><span><?=e(t('Type de suivi'))?></span><select name="kind"><?php foreach(StudentAdminHistory::KINDS as $value=>$label): ?><option value="<?=$value?>"><?=e(t($label))?></option><?php endforeach; ?></select></label><label class="field"><span><?=e(t('Date et heure'))?></span><input type="datetime-local" name="occurred_at" required value="<?=e((new DateTimeImmutable('now',new DateTimeZone('Europe/Zurich')))->format('Y-m-d\TH:i'))?>"></label></div><label class="field"><span><?=e(t('Parcours (facultatif)'))?></span><select name="course_id"><option value="0"><?=e(t('Sans parcours'))?></option><?php foreach($courses as $course): ?><option value="<?=(int)$course['id']?>"><?=e($course['title'])?></option><?php endforeach; ?></select></label><label class="field"><span><?=e(t('Modèle'))?></span><select name="template_id"><option value="0"><?=e(t('Choisir un modèle'))?></option><?php foreach($templates as $template): ?><option value="<?=(int)$template['id']?>"><?=e($template['name'])?></option><?php endforeach; ?></select></label><label class="field"><span><?=e(t('Titre'))?></span><input name="title" maxlength="160" required></label><label class="field"><span><?=e(t('Compte rendu en Markdown'))?></span><textarea name="body" maxlength="5000" rows="8" required></textarea></label><?php render_message_variables(); ?><small><?=e(t('Pour un suivi collectif, {prenom} et {nom} regroupent les participants.'))?></small></section></div><p class="followup-save-note"><?=e(t('Ce suivi reste dans l’historique administratif. Aucun courriel n’est envoyé.'))?></p><p data-followup-feedback role="status" hidden></p><div class="content-block followup-preview" data-followup-preview hidden></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal"><?=e(t('Fermer'))?></button><button type="button" class="btn btn-outline-primary" data-followup-preview-button><?=e(t('Aperçu'))?></button><button class="btn btn-primary" data-followup-save><?=e(t('Enregistrer le suivi'))?></button></div></form></div></div></div><?php
}
